// --- Estimation des tokens (repli si l API ne renvoie pas usage) -------
const CHARS_TOKEN_ENVOI = 4.3;
const CHARS_TOKEN_SORTIE = 5.5;
const estIn = s => Math.round(String(s == null ? '' : s).length / CHARS_TOKEN_ENVOI);
const estOut = s => { const n = String(s == null ? '' : s).length; return n ? Math.max(1, Math.round(n / CHARS_TOKEN_SORTIE)) : 0; };

const runs = $('Eclater les executions').all();

// Lit une reponse Anthropic (content: [{type:'text', text}]) ou OpenAI (choices).
function extraireTexte(json) {
  if (!json) return '';
  if (Array.isArray(json.content)) {
    return json.content.map(p => (p && typeof p.text === 'string') ? p.text : '').join('');
  }
  if (Array.isArray(json.choices) && json.choices[0] && json.choices[0].message) {
    return String(json.choices[0].message.content || '');
  }
  if (typeof json.text === 'string') return json.text;
  if (typeof json.content === 'string') return json.content;
  return '';
}
const tIn = u => u ? (u.input_tokens != null ? u.input_tokens : u.prompt_tokens) : null;
const tOut = u => u ? (u.output_tokens != null ? u.output_tokens : u.completion_tokens) : null;

return $input.all().map((item, i) => {
  const r = runs[i] ? runs[i].json : {};
  const erreur = item.json && item.json.error ? String(item.json.error.message || item.json.error) : '';
  const u = (item.json && item.json.usage) || null;
  const sortie = String(extraireTexte(item.json)).trim();
  return { json: {
    campagneId: r.campagneId,
    casId: r.casId,
    entree: r.entree,
    attendu: r.attendu,
    repetition: r.repetition,
    mode: r.mode,
    prompt: r.prompt,
    sortie,
    erreur,
    tokensInExec: u ? tIn(u) : estIn(r.prompt) + estIn(r.entree),
    tokensOutExec: u ? tOut(u) : estOut(sortie),
    tokensReels: !!u
  } };
});

// Le juge recoit a chaque appel son system prompt, le prompt teste,
// l entree, la reponse attendue et la sortie obtenue.
const CHARS_TOKEN_ENVOI = 4.3;
const CHARS_TOKEN_JSON = 4.1;
const TOKENS_SYS_JUGE = 345;
const estIn = s => Math.round(String(s == null ? '' : s).length / CHARS_TOKEN_ENVOI);
const estJson = s => Math.round(String(s == null ? '' : s).length / CHARS_TOKEN_JSON);

const sources = $('Normaliser la sortie').all();

function extraireTexte(json) {
  if (!json) return '';
  if (Array.isArray(json.content)) {
    return json.content.map(p => (p && typeof p.text === 'string') ? p.text : '').join('');
  }
  if (Array.isArray(json.choices) && json.choices[0] && json.choices[0].message) {
    return String(json.choices[0].message.content || '');
  }
  if (typeof json.text === 'string') return json.text;
  if (typeof json.content === 'string') return json.content;
  return '';
}
const tIn = u => u ? (u.input_tokens != null ? u.input_tokens : u.prompt_tokens) : null;
const tOut = u => u ? (u.output_tokens != null ? u.output_tokens : u.completion_tokens) : null;

function parser(txt) {
  const nettoye = String(txt).replace(/```json/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(nettoye); } catch (e) {}
  const d = nettoye.indexOf('{');
  const f = nettoye.lastIndexOf('}');
  if (d !== -1 && f > d) {
    try { return JSON.parse(nettoye.slice(d, f + 1)); } catch (e) {}
  }
  return null;
}

return $input.all().map((item, i) => {
  const base = sources[i] ? sources[i].json : {};
  const brut = extraireTexte(item.json);
  const u = (item.json && item.json.usage) || null;
  const verdict = parser(brut);
  const score = verdict && typeof verdict.score === 'number' ? Math.max(0, Math.min(10, Math.round(verdict.score))) : null;
  const reussi = verdict ? (verdict.verdict === true || (score !== null && score >= 7)) : false;
  return { json: Object.assign({}, base, {
    reussi,
    score: score !== null ? score : (reussi ? 10 : 0),
    justification: verdict ? String(verdict.justification || '') : 'The judge did not return a usable verdict',
    tokensInJuge: u ? tIn(u) : TOKENS_SYS_JUGE + estIn(base.prompt) + estIn(base.entree) + estIn(base.attendu) + estIn(base.sortie),
    tokensOutJuge: u ? tOut(u) : estJson(brut),
    tokensReels: base.tokensReels !== false && !!u
  }) };
});

const lignes = $input.all().map(i => i.json);
const campagne = $('Recevoir la campagne').first().json;
const tronc = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n) + '...' : s; };

// --- Grille tarifaire ---------------------------------------------------
// claude-haiku-4-5 sur l API Anthropic : 1 USD par million de tokens en entree,
// 5 USD par million en sortie. Les prix changent : c est un parametre, pas une
// verite. Il est renvoye a l application pour etre affiche sous le cout.
const MODELE = 'claude-haiku-4-5';
const PRIX_IN = 1;    // USD par million de tokens en entree
const PRIX_OUT = 5;   // USD par million de tokens en sortie
const usd = (tin, tout) => Math.round(((tin * PRIX_IN + tout * PRIX_OUT) / 1e6) * 1e6) / 1e6;

const parCas = {};
lignes.forEach(l => {
  if (!parCas[l.casId]) {
    parCas[l.casId] = { casId: l.casId, entree: l.entree, attendu: l.attendu, sorties: [], scores: [], justifs: [], reussites: 0, total: 0, tIn: 0, tOut: 0 };
  }
  const c = parCas[l.casId];
  c.total += 1;
  if (l.reussi) c.reussites += 1;
  c.sorties.push(String(l.sortie == null ? '' : l.sortie));
  if (typeof l.score === 'number') c.scores.push(l.score);
  if (l.justification) c.justifs.push(String(l.justification));
  c.tIn += (l.tokensInExec || 0) + (l.tokensInJuge || 0);
  c.tOut += (l.tokensOutExec || 0) + (l.tokensOutJuge || 0);
});

const cas = Object.values(parCas).map(c => {
  const distinctes = Array.from(new Set(c.sorties.map(s => s.toLowerCase().trim())));
  const scoreMoyen = c.scores.length ? Math.round(c.scores.reduce((a, b) => a + b, 0) / c.scores.length * 10) / 10 : null;
  const scoreMin = c.scores.length ? Math.min.apply(null, c.scores) : null;
  const scoreMax = c.scores.length ? Math.max.apply(null, c.scores) : null;
  let statut = 'echec';
  if (c.reussites === c.total) statut = 'reussi';
  else if (c.reussites > 0) statut = 'instable';
  return {
    casId: c.casId,
    entree: c.entree,
    attendu: c.attendu,
    reussites: c.reussites,
    total: c.total,
    statut,
    stable: distinctes.length === 1,
    sortiesDistinctes: distinctes.length,
    exemple: c.sorties[0] || '',
    scoreMoyen,
    scoreMin,
    scoreMax,
    tokensIn: c.tIn,
    tokensOut: c.tOut,
    cout: usd(c.tIn, c.tOut),
    apercu: distinctes.slice(0, 3).map(s => tronc(s, 700)),
    justifications: Array.from(new Set(c.justifs)).slice(0, 3).map(s => tronc(s, 200))
  };
});

const totalAppels = lignes.length;
const totalReussites = lignes.filter(l => l.reussi).length;
const tauxReussite = totalAppels ? Math.round((totalReussites / totalAppels) * 1000) / 10 : 0;
const casInstables = cas.filter(c => c.statut === 'instable' || (c.scoreMax !== null && c.scoreMax - c.scoreMin >= 2)).length;
const casEchoues = cas.filter(c => c.statut === 'echec').length;
const tousScores = lignes.filter(l => typeof l.score === 'number').map(l => l.score);
const scoreMoyen = tousScores.length ? Math.round(tousScores.reduce((a, b) => a + b, 0) / tousScores.length * 10) / 10 : null;

// --- Ventilation des tokens en trois postes -----------------------------
const somme = (f) => lignes.reduce((a, l) => a + (l[f] || 0), 0);
const tokens = {
  execIn: somme('tokensInExec'),
  execOut: somme('tokensOutExec'),
  jugeIn: somme('tokensInJuge'),
  jugeOut: somme('tokensOutJuge'),
  revIn: 0,
  revOut: 0
};

const resumeAnalyse = cas.map(c => ({
  cas: c.casId,
  entree: tronc(c.entree, 300),
  attendu: c.attendu || null,
  resultat: c.reussites + '/' + c.total,
  statut: c.statut,
  scores_par_repetition: c.scores,
  ecart_de_score: c.scoreMax !== null ? c.scoreMax - c.scoreMin : null,
  sorties_observees: c.apercu,
  verdicts: c.justifications
}));

const detail = lignes.map(l => ({
  campagneId: l.campagneId,
  casId: l.casId,
  repetition: l.repetition,
  entree: l.entree,
  attendu: l.attendu,
  sortie: l.sortie,
  reussi: l.reussi ? 'oui' : 'non',
  score: typeof l.score === 'number' ? l.score : '',
  justification: l.justification || '',
  erreur: l.erreur || '',
  tokensIn: (l.tokensInExec || 0) + (l.tokensInJuge || 0),
  tokensOut: (l.tokensOutExec || 0) + (l.tokensOutJuge || 0)
}));

return [{ json: {
  campagneId: campagne.campagneId,
  nom: campagne.nom,
  mode: campagne.mode,
  prompt: campagne.prompt,
  temperature: campagne.temperature,
  repetitions: campagne.repetitions,
  tauxReussite,
  scoreMoyen,
  totalAppels,
  totalReussites,
  casInstables,
  casEchoues,
  nbCas: cas.length,
  cas,
  tokens,
  tarif: { modele: MODELE, prixIn: PRIX_IN, prixOut: PRIX_OUT },
  tokensReels: lignes.length > 0 && lignes.every(l => l.tokensReels === true),
  resumeAnalyse,
  detail
} }];

// Comparaison stricte, apres normalisation : minuscules, accents retires,
// ponctuation finale retiree, espaces rognes.
// Volontairement SANS repli sur "la reponse attendue est contenue dans la
// sortie" : ce repli laissait passer un paragraphe entier des lors qu il
// mentionnait le mot attendu, ce qui contredit la promesse de l interface
// ("must match the expected answer word for word"). Pour accepter une
// formulation differente a sens egal, c est le mode Juge qui sert.
function normaliser(valeur) {
  return String(valeur == null ? '' : valeur)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[.!?;:,]+$/g, '')
    .trim();
}

const tronc = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n) + '...' : s; };

return $input.all().map(item => {
  const j = item.json;
  const sortie = normaliser(j.sortie);
  const attendu = normaliser(j.attendu);
  let reussi = false;
  let justification = '';

  if (j.erreur) {
    justification = 'Call failed: ' + j.erreur;
  } else if (!sortie) {
    justification = 'Empty output';
  } else if (sortie === attendu) {
    reussi = true;
    justification = 'Exact match';
  } else if (sortie.indexOf(attendu) !== -1) {
    justification = 'Expected exactly "' + j.attendu + '", got ' + tronc(j.sortie, 80) + ' (the expected value is in there, but the output is not it)';
  } else {
    justification = 'Expected "' + j.attendu + '", got ' + tronc(j.sortie, 80);
  }

  // La comparaison exacte ne consomme aucun token : c est du code, pas un modele.
  return { json: Object.assign({}, j, {
    reussi, score: reussi ? 10 : 0, justification,
    tokensInJuge: 0, tokensOutJuge: 0
  }) };
});

const base = $('Agreger la campagne').first().json;

// Le reviseur est un troisieme appel, une seule fois par campagne.
const CHARS_TOKEN_ENVOI = 4.3;
const CHARS_TOKEN_JSON = 4.1;
const TOKENS_SYS_REVISEUR = 675;
const estIn = s => Math.round(String(s == null ? '' : s).length / CHARS_TOKEN_ENVOI);
const estJson = s => Math.round(String(s == null ? '' : s).length / CHARS_TOKEN_JSON);

function extraireTexte(json) {
  if (!json) return '';
  if (Array.isArray(json.content)) {
    return json.content.map(p => (p && typeof p.text === 'string') ? p.text : '').join('');
  }
  if (Array.isArray(json.choices) && json.choices[0] && json.choices[0].message) {
    return String(json.choices[0].message.content || '');
  }
  if (typeof json.text === 'string') return json.text;
  if (typeof json.content === 'string') return json.content;
  return '';
}
const tIn = u => u ? (u.input_tokens != null ? u.input_tokens : u.prompt_tokens) : null;
const tOut = u => u ? (u.output_tokens != null ? u.output_tokens : u.completion_tokens) : null;

function parser(txt) {
  const nettoye = String(txt).replace(/```json/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(nettoye); } catch (e) {}
  const d = nettoye.indexOf('{');
  const f = nettoye.lastIndexOf('}');
  if (d !== -1 && f > d) {
    try { return JSON.parse(nettoye.slice(d, f + 1)); } catch (e) {}
  }
  return null;
}

const brut = extraireTexte($input.first().json);
const u = ($input.first().json && $input.first().json.usage) || null;
const analyse = parser(brut) || {};
const problemes = Array.isArray(analyse.problemes) ? analyse.problemes : [];
const changements = Array.isArray(analyse.changements) ? analyse.changements : [];

// --- Comptes finaux -----------------------------------------------------
// Le modele teste (execution) est claude-haiku-4-5, au tarif renvoye par l agregation.
// Le juge et le reviseur tournent sur claude-sonnet-4-5 : 3 USD / 15 USD par million.
const tarif = base.tarif || { modele: 'inconnu', prixIn: 0, prixOut: 0 };
const OUTIL = { modele: 'claude-sonnet-4-5', prixIn: 3, prixOut: 15 };
const t = Object.assign({ execIn: 0, execOut: 0, jugeIn: 0, jugeOut: 0 }, base.tokens, {
  revIn: u ? tIn(u) : TOKENS_SYS_REVISEUR + estIn(base.prompt) + estIn(JSON.stringify(base.resumeAnalyse || [])),
  revOut: u ? tOut(u) : estJson(brut)
});

const arr = x => Math.round(x * 1e6) / 1e6;
const usdExec = (tin, tout) => arr((tin * tarif.prixIn + tout * tarif.prixOut) / 1e6);
const usdOutil = (tin, tout) => arr((tin * OUTIL.prixIn + tout * OUTIL.prixOut) / 1e6);
const tokensEntree = t.execIn + t.jugeIn + t.revIn;
const tokensSortie = t.execOut + t.jugeOut + t.revOut;

// En production on paie l execution seule, pas le juge ni le reviseur,
// qui sont l outillage de test. C est ce chiffre qu il faut projeter.
const appels = base.totalAppels || 1;
const execution = usdExec(t.execIn, t.execOut);
const jugement = usdOutil(t.jugeIn, t.jugeOut);
const revision = usdOutil(t.revIn, t.revOut);
const coutParAppel = Math.round((execution / appels) * 1e8) / 1e8;

const cout = {
  total: arr(execution + jugement + revision),
  execution,
  jugement,
  revision,
  parAppelProduction: coutParAppel,
  modele: tarif.modele,
  prixIn: tarif.prixIn,
  prixOut: tarif.prixOut,
  modeleOutil: OUTIL.modele,
  estime: !(base.tokensReels && u)
};

return [{ json: Object.assign({}, base, {
  diagnostic: String(analyse.diagnostic || ''),
  promptCorrige: String(analyse.promptCorrige || ''),
  confianceAnalyse: String(analyse.confiance || ''),
  problemes,
  changements,
  analyseJson: JSON.stringify({ problemes, changements, confiance: analyse.confiance || '' }),
  analyseOk: !!analyse.promptCorrige,
  tokens: t,
  tokensEntree,
  tokensSortie,
  cout,
  coutJson: JSON.stringify(cout)
}) }];

// Les resultats viennent d etre ecrits ligne a ligne.
// On revient a l item unique de l agregation pour lancer le reviseur une seule fois.
return [$('Agreger la campagne').first()];
